It is well known since late 60's [Pow] that a translation invariant state $\omega$ 
on ${\mathcal B}$ is a factor state if and only if 

\begin{equation} 
\mbox{sup}_{x \in {\mathcal B}_{\Lambda_n^c}, ||x|| \le 1}|\omega(xy)) - \omega(x)\omega(y)| \rightarrow 0
\end{equation} 
for all $y \in {\mathcal B}$ as $n \rightarrow \infty$, where $\Lambda_{n}$ is the local algebra with support in the finite set $\{\bar{m}: -n \le m_k \le n \}$.

First we recall that the Cuntz algebra ${\mathcal O}_d ( d \in \{2,3,.., \} )$ [Cun] is the universal unital $C^*$-algebra generated by the elements $\{s_1,s_2,...,
s_d \}$ subject to the following Cuntz relations:
\begin{equation} 
s^*_is_j=\delta^i_j1,\;\;\sum_{1 \le i \le d } s_is^*_i=1
\end{equation}

We also define the canonical endomorphism $\lambda$ on ${\mathcal O}_d$ by
\begin{equation} 
\lambda(x)=\sum_{1 \le i \le d}s_ixs^*_i
\end{equation}

Furthermore a crucial 
point to be noted that the support projection of $\psi$ in $\pi({\mathcal O}_d)''$ being equal to $P$, by our construction we have 
\begin{equation} 
\{x \in {\mathcal B}({\mathcal K}): \sum_i v_ixv_i^* = x \}= {\mathcal M}'
\end{equation}

For a faithful normal state $\phi$ on ${\mathcal M}$
we define state $\psi$ on ${\mathcal O}_d$ by 
\begin{equation} 
\psi(s_Is_J^*)=\phi(v_Iv_J^*)
\end{equation}

We verify also with $v_i^*=PS^*_iP$ that 
\begin{equation} 
\omega_R(|e_{i_1}><e_{j_1}| \otimes |e_{i_2}><e_{j_2}| \otimes ...\otimes |e_{i_n}><e_{j_n}|)= \phi(v_Iv_J^*)
\end{equation}       
where $v_I=v_{i_n}...v_{i_2}v_{i_1}$ and $v^*_J=v_{j_1}^*v^*_{j_2}...v^*_{j_n}$.

The state $\phi(x)=<\Omega,x \Omega>$ on ${\mathcal M}$ being faithful and invariant of $\tau:{\mathcal M} \rightarrow {\mathcal M}$ we find a unique unital completely positive map 
$\tilde{\tau}:{\mathcal M}' \rightarrow {\mathcal M}'$ satisfying the duality  relation 
\begin{equation} 
<y\Omega,\tau(x)\Omega>= <\tilde{\tau}(y)\Omega,x\Omega>
\end{equation}
for all $x \in {\mathcal M}$ and $y \in {\mathcal M}'$, where ${\mathcal M}'$ is the commutant of ${\mathcal M}$ in ${\mathcal B}({\mathcal H})$.

By KMS or modular relation [BR vol-I] we verify that 
$$\sum_k \tilde{v}_k \tilde{v}_k^*=1$$ 
and
\begin{equation} 
\tilde{\tau}(y)=\sum_k \tilde{v}_ky\tilde{v}^*_k
\end{equation}
and 
\begin{equation}
\phi(v_Iv^*_J)= \phi(\tilde{v}_{\tilde{I}}\tilde{v}^*_{\tilde{J}})
\end{equation}
where $\tilde{I}=(i_n,..,i_2,i_1)$ if $I=(i_1,i_2,...,i_n)$.

The major problem that we 
will address in the text when do we have the following equality: 
\begin{equation} 
\{x \in {\mathcal B}({\mathcal K}): \sum_k \tilde{v}_kx\tilde{v}_k^*= x \} ={\mathcal M}
\end{equation}

A unital completely positive map $\tau$ on a von-Neumann algebra ${\mathcal M}$ 
with an invariant normal state $\phi$ [BJKW,Mo1] is called {\it ergodic} if 
\begin{equation} 
{1 \over N}\sum_{0 \le k \le N-1}\tau^k(x) \rightarrow  \phi(x)I
\end{equation} 
as $N \rightarrow \infty$ in weak$^*$ topology for all $x \in {\mathcal M}$.

For a translation invariant factor state $\omega$ on ${\mathcal B}$, we say it admits {\it Haag duality } property if 
\begin{equation} 
\pi_{\omega}({\mathcal B}_R)'= \pi_{\omega}({\mathcal B}_L)''
\end{equation}

For von-Neumann algebras ${\mathcal N} \subseteq {\mathcal M}$, a normal unital completely positive map $E_c:{\mathcal M} \rightarrow {\mathcal N}$ is called 
{\it normal conditional expectation } if 
\begin{equation} 
E_c(yxz)=yE_c(x)z
\end{equation}
for all $y,z \in {\mathcal N}$ and $x \in {\mathcal M}$.

We also consider the state $\tilde{\psi}$ on $\tilde{{\mathcal O}}_d$ given by
\begin{equation} 
\tilde{\psi}(\tilde{s}_I\tilde{s}_J^*)=\phi(\tilde{v}_I\tilde{v}^*_J)
\end{equation}

Let $\omega$ be a translation invariant factor state on ${\mathcal B}$ and $\psi$ be an extremal element in $K_{\omega}$. Then the following statements are equivalent:

\vskip 1em 
\noindent (a) $[{\mathcal M}^1_0\Omega]=I_{{\mathcal K}_0},\;[\tilde{{\mathcal M}}^1_0\Omega]=I_{{\mathcal K}_0}$;

\vskip 1em 
\noindent (b) $({\mathcal M}^1_0)'=\tilde{{\mathcal M}}^1_0$; 

\vskip 1em         
\noindent (c) $\pi_{\omega}({\mathcal B}_R)'=\pi_{\omega}({\mathcal B}_L)''$;

\vskip 1em 
\noindent (d) $[\pi_{\omega}({\mathcal B}_R)'\Omega]=[\pi_{\omega}({\mathcal B}_L)''\Omega]$;

\vskip 1em 
\noindent (e) $\{x \in {\mathcal B}({\mathcal K}): \sum_k \tilde{v}_kx\tilde{v}_k^*= x \} ={\mathcal M}$; 

\vskip 1em 
\noindent (f) $\omega$ is pure.

\vskip 1em 
In such a case $\tilde{{\mathcal M}}^1_0 = \{x \in \tilde{{\mathcal M}}: \beta_z(x)=x: z \in H \}$ where 
$H=\{ z \in S^1:\psi = \psi \beta_z \}$.

$\Lambda(P)$ is also a projection in $\pi_{\psi}({\mathcal O}_d)''$ so that
$\psi_{\Omega}(\Lambda(P))=1$ by invariance property. Thus we have $\Lambda(P) \ge P$ i.e.
$P\Lambda(I-P)P=0$. Hence we have
\begin{equation}
PS^*_kP=S^*_kP
\end{equation}

Moreover by $\lambda$ invariance property we also note that the faithful normal state
$\phi(x)=<\Omega,x\Omega>$ on the von-Neumann algebra ${\mathcal M}=P\pi_{\psi}({\mathcal O}_d)''P$
is invariant for the reduced Markov map [Mo1] on ${\mathcal M}$ given by
\begin{equation}
\tau(x)=P\Lambda(PxP)P
\end{equation}

For any projection $E$ in the centre of $\pi(\tilde{\mbox{UHF}}_d \otimes \mbox{UHF}_d)''$, via the unitary equivalence, we note 
that $EE'=E'EE'$ is an element in the centre of $\pi_{\Omega}(\tilde{\mbox{UHF}}_d \otimes \mbox{UHF}_d)''$. $\omega$ being a 
factor state we conclude that $EE'$ is a scalar multiple of $E'$ and so we have
\begin{equation}
EE'=\omega(E)E'
\end{equation}
Thus we also have $EYE'=\omega(E)YE'$ for all $Y \in \pi(\tilde{\mbox{UHF}}_d \otimes \mbox{UHF}_d)'$ and so 
\begin{equation}
EE_0=\omega(E)E_0
\end{equation}

(C1) For each $1 \le \alpha \le n_{\pi_1} $ we have 
$U \Omega^1_{\alpha} = \Omega^2_{\alpha'}$ for some 
$1 \le \alpha' \le n_{\pi_2}$;

By extending isometry $U_{12}$ to an isometry from $H_1 \rightarrow n_{\pi_{max}} H_{\pi_{max}}$ trivially we get the 
required isometry that satisfies (C1),(C2) and (C3) where cardinal numbers $n_{\pi_{max}} = \sum_{\pi \in {\mathcal P}_0} 
n_{\pi} \in \aleph_0$. Thus by maximal property of ${\mathcal P}_0$ we have $\pi_{max} \in {\mathcal P}_0$.

We set unitary operator $V=\sum_k S_k\tilde{S}^*_k$. That $V$ is a unitary operator follows by Cuntz's relations and commuting property 
of $(S_i)$ and $(\tilde{S}_i)$. Further a simple computation shows that $V\pi(x)V^*=\pi(\theta(x))$ for all $x \in {\mathcal B} = {\mathcal B}_L \otimes {\mathcal B}_R$, 
identified with $\tilde{\mbox{UHF}}_d \otimes \mbox{UHF}_d$ and $\theta$ is the right shift. We also have    
\begin{equation} 
\theta({\mathcal E})=V {\mathcal E} V^*= \sum_{k,k'}S_k\tilde{S}^*_k {\mathcal E} S^*_{k'}\tilde{S}_{k'}=\Lambda({\mathcal E}) \ge {\mathcal E}
\end{equation} 
Similarly we also have
\begin{equation} 
\theta(\tilde{{\mathcal F}}) \ge \tilde{{\mathcal F}} 
\end{equation}

So in particular we have $V(I-{\mathcal E})V^* \le I-{\mathcal E}$, i.e. $(I-{\mathcal E})V^*{\mathcal E}=0$.  
Also for any $X \in \pi({\mathcal O}_d)'$ we have $V^*\tilde{{\mathcal F}}X\Omega = 
\tilde{{\mathcal F}} \sum_k \tilde{S}_k X \tilde{S}_k^*\Omega$ as $S_k^*\Omega 
=\tilde{S}_k^*\Omega$. Thus $(I-\tilde{{\mathcal F}})V^*\tilde{{\mathcal F}}=0$ i.e. 
$V\tilde{{\mathcal F}}V^*=\Lambda(\tilde{{\mathcal F}}) \ge \tilde{{\mathcal F}}$. Similarly we also 
have 
\begin{equation} 
\theta^{-1}(\tilde{{\mathcal E}})=V^*\tilde{{\mathcal E}}V \ge \tilde{{\mathcal E}}\;\mbox{and}\; V^* {\mathcal F} V \ge {\mathcal F}
\end{equation}

We also set two family of increasing projections for all natural numbers $n \in \mathbb{Z}$ as follows 
\begin{equation} 
{\mathcal E}_n=V^n {\mathcal E} (V^n)^*,\;\;\tilde{{\mathcal F}}_n=V^n\tilde{{\mathcal F}}(V^n)^*
\end{equation}

(C1) For each $1 \le \alpha \le n_{\pi_1} $ we have 
$U \Omega^1_{\alpha} = \Omega^2_{\alpha'}$ for some 
$1 \le \alpha' \le n_{\pi_2}$;

Now we set projection ${\mathcal F}'$ defined by 
\begin{equation} 
{\mathcal F}'={\mathcal F}-{\mathcal F}\tilde{{\mathcal F}}+|\Omega><\Omega|
\end{equation} 
and check by commuting property of $\tilde{{\mathcal F}}$ with ${\mathcal F}$ that 
$$ 
{\mathcal F}'\theta^{-1}({\mathcal F}'){\mathcal F}' = (I-\tilde{{\mathcal F}}){\mathcal F}\theta^{-1}({\mathcal F})(I-\theta^{-1}(\tilde{{\mathcal F}}))(I-\tilde{{\mathcal F}}){\mathcal F} 
+ |\Omega><\Omega|$$ 
$$= {\mathcal F}(I-\tilde{{\mathcal F}}) + |\Omega><\Omega|={\mathcal F}'$$ 
where we have used $\theta^{-1}({\mathcal F}) = \tilde{\Lambda}({\mathcal F}) \ge {\mathcal F},\; \theta({\mathcal F}) \le {\mathcal F}$ and  
$\theta(\tilde{{\mathcal F}}) = \Lambda(\tilde{{\mathcal F}}) \ge \tilde{{\mathcal F}}$. 
Thus we get 
\begin{equation} 
\theta^{-1}({\mathcal F}') \ge {\mathcal F}'
\end{equation}
